#!/usr/bin/env bash
set -euo pipefail
ROOT=$(cd "$(dirname "$0")/.."&&pwd);OUT=$ROOT/work/results/l5_all_primitives;mkdir -p "$OUT";R=$ROOT/scripts/run_memory_capped.sh;V=$ROOT/work/toolchain/conda/bin/verilator
"$ROOT/scripts/generate_all_hardfloat_primitives.sh";taskset -c 8-23 "$ROOT/work/toolchain/cnn_py312/bin/python" "$ROOT/scripts/generate_bf16_array_expected.py" --rows 2 --cols 2 --steps 4 --output "$ROOT/work/results/l5_bf16_array/expected.memh"
MIN_AVAILABLE_KIB=10485760 MEMORY_HIGH=24G MEMORY_MAX=30G "$R" "$V" --binary --timing -Wall -Wno-DECLFILENAME -Wno-TIMESCALEMOD -Wno-UNUSEDSIGNAL -j 8 -MAKEFLAGS "AR=/usr/bin/ar CXX=/usr/bin/g++" -GROWS=2 -GCOLS=2 --top-module tb_bf16_outer_product_array --Mdir "$OUT/obj_bf16" -o tb "$ROOT/work/generated/l5_all_primitives/HeteroAllPrimitives.sv" "$ROOT/rtl/matrix/bf16_outer_product_array.sv" "$ROOT/tb/tb_bf16_outer_product_array.sv" >"$OUT/bf16_build.log" 2>&1;MIN_AVAILABLE_KIB=10485760 MEMORY_HIGH=24G MEMORY_MAX=30G "$R" "$OUT/obj_bf16/tb"|tee "$OUT/bf16.log"
MIN_AVAILABLE_KIB=10485760 MEMORY_HIGH=24G MEMORY_MAX=30G "$R" "$V" --binary --timing -Wall -Wno-DECLFILENAME -Wno-TIMESCALEMOD -Wno-UNUSEDSIGNAL -j 8 -MAKEFLAGS "AR=/usr/bin/ar CXX=/usr/bin/g++" --top-module tb_fp32_rmsnorm16 --Mdir "$OUT/obj_rms" -o tb "$ROOT/work/generated/l5_all_primitives/HeteroAllPrimitives.sv" "$ROOT/rtl/sfu/fp32_rsqrt_nr.sv" "$ROOT/rtl/sfu/fp32_rmsnorm16.sv" "$ROOT/tb/tb_fp32_rmsnorm16.sv" >"$OUT/rms_build.log" 2>&1;MIN_AVAILABLE_KIB=10485760 MEMORY_HIGH=24G MEMORY_MAX=30G "$R" "$OUT/obj_rms/tb"|tee "$OUT/rms.log"
echo L5_ALL_PRIMITIVES_SMOKE_PASS
